sp_widget.client_script:
api.controller = function($rootScope, $location, $window) {

  /* =========================================================
     GATENOW · SIDEBAR · Client script

     The rail owns its own collapsed state and tells the rest of
     the page about it, rather than each page guessing. Any page
     hosting this widget listens for gnSidebar and sizes its
     column to match.
     ========================================================= */

  var c = this;

  /* expanded by default. A rail with labels is only worth
     having if people see it labelled at least once. */
  c.tight = false;

  function announce() {
    /* the width the host column should reserve */
    $rootScope.$broadcast('gnSidebar', {
      collapsed: c.tight,
      width: c.tight ? 72 : 236
    });
  }

  c.toggle = function() {
    c.tight = !c.tight;
    announce();
  };

  /* say it once on load so a page rendered after the rail still
     gets the right width */
  announce();

  c.go = function(item) {
    if (!item || !item.page) return;

    /* already here, so nothing to do. Reloading the page you are
       on throws away scroll position for no reason. */
    if (item.active) return;

    $location.search({ id: item.page });
  };

};

sp_widget.css:
/* =========================================================
   GATENOW · SIDEBAR
   Service Portal widget · CSS / SCSS

   Selectors are written out in full. The Service Portal Sass
   compiler does not support parent selector concatenation.

   WHAT THIS FIXES, AND WHY

   1. Hover was stronger than active.
      The old rail filled the circle solid blue on hover and
      left the active item white. So pointing at any item made
      it look more selected than the page you were actually on.
      Active is now the only filled state, and hover is a quiet
      tint that never competes with it.

   2. Glass over a pale page is not glass.
      A 35% white panel with a blur, sitting on an almost white
      dashboard, reads as nothing at all. The icons appeared to
      float over the content and the tooltips bled across the
      cards. This is a solid white surface with one hairline,
      which is what actually separates two regions.

   3. 120px for six icons.
      Icon only rails are 64 to 72. Anything wider is either
      carrying labels or wasting the column. This one carries
      labels at 236 and collapses to 72.

   4. The external font import is gone.
      @import from fonts.googleapis.com is an outbound request
      from CSS, which fails a Store submission and loads a
      second typeface next to the one every other widget uses.
      The rail inherits Outfit like everything else.

   5. Brand mark + name are now a real click target.
      They sit inside a single .gsb-brand__link so the whole
      lockup can navigate home, keyboard and screen reader
      accessible, without disturbing the flex layout the old
      .gsb-brand row already had. Click/tap has NO visual
      highlight (no background flash, no opacity dim, no
      outline on mouse/touch); a focus ring appears only for
      keyboard navigation via :focus-visible.

   Also: the indigo shadow was the old palette. Everything here
   is the same navy and the same accent blue as the pages.
   ========================================================= */

/* =========================================================
   HOST COLUMN
   =========================================================

   THE OVERLAP

   Every page wraps this widget in a column that reserves a
   fixed width through an inline ng-style:

     ng-style="{'width': c.isSidebarCollapsed ? '64px' : '96px',
                'min-width': ..., 'max-width': ..., 'flex': ...}"

   The rail is 236px when it carries labels. The column is 96.
   So the rail paints 140px of itself over the page next to it,
   which is exactly what the screenshots show.

   Rather than editing seven templates, the column is corrected
   from here. An inline style loses to a stylesheet rule marked
   important, so these win over the ng-style without the pages
   changing at all, and they keep working when the rail toggles
   between 236 and 72.

   The pages can still be cleaned up later, and the note that
   ships with this widget says how. Nothing breaks if they are
   not.
   ========================================================= */

.aw-sidebar,
.gatenow-sidebar-wrapper,
.gn-layout > .sidebar,
.main-layout-flex > .sidebar {
  width: auto !important;
  min-width: 0 !important;
  max-width: none !important;
  flex: 0 0 auto !important;
  height: auto !important;
  overflow: visible !important;
  background: transparent !important;
}

/* the rail does its own sticking, so a second sticky wrapper
   around it fights with the first and neither wins */
.aw-sidebar,
.gatenow-sidebar-wrapper {
  position: relative !important;
  top: auto !important;
}

/* Service Portal wraps every widget in a panel that clips
   anything leaving its box, which cuts the tooltips off at the
   column edge */
.aw-sidebar .panel,
.aw-sidebar .panel-body,
.aw-sidebar .sp-widget,
.gatenow-sidebar-wrapper .panel,
.gatenow-sidebar-wrapper .panel-body,
.gatenow-sidebar-wrapper .sp-widget {
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  overflow: visible !important;
}


/* ---------- ink ---------- */
$s-navy:   #0a2540;
$s-ink-2:  rgba(10, 37, 64, 0.72);
$s-ink-3:  rgba(10, 37, 64, 0.54);
$s-ink-4:  rgba(10, 37, 64, 0.38);
$s-line:   rgba(10, 37, 64, 0.10);
$s-line-2: rgba(10, 37, 64, 0.06);
$s-tint:   rgba(10, 37, 64, 0.035);

/* ---------- accent ---------- */
$s-blue:    #1560e0;
$s-blue-dk: #0f4cbb;
$s-blue-1:  rgba(21, 96, 224, 0.09);
$s-blue-2:  rgba(21, 96, 224, 0.18);

/* ---------- badges, two meanings only ---------- */
$s-amber:   #a4741f;
$s-amber-1: rgba(164, 116, 31, 0.14);
$s-red:     #b8394a;
$s-red-1:   rgba(184, 57, 74, 0.12);

$s-white: #ffffff;
$s-ease:  cubic-bezier(0.45, 0.05, 0.25, 1);

$s-font: "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;


/* =========================================================
   RAIL
   ========================================================= */

.gsb {
  position: sticky;
  top: 0;
  display: flex;
  flex-direction: column;

  /* the rail is the thing that knows how wide it is. The column
     around it is told to fit, above. */
  width: 236px;
  min-width: 236px;
  max-width: 236px;

  height: 100vh;
  flex-shrink: 0;
  background: $s-white;
  border-right: 1px solid $s-line;
  font-family: $s-font;
  color: $s-navy;
  overflow: visible;
  z-index: 30;
  transition: width 0.32s $s-ease;
}

.gsb *,
.gsb *::before,
.gsb *::after { box-sizing: border-box; }

.gsb.is-tight {
  width: 72px;
  min-width: 72px;
  max-width: 72px;
}


/* =========================================================
   BRAND
   ========================================================= */

.gsb-brand {
  position: relative;
  display: flex;
  align-items: center;
  gap: 11px;
  height: 68px;
  padding: 0 16px;
  border-bottom: 1px solid $s-line-2;
  flex-shrink: 0;
}

.gsb-brand__mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  border-radius: 10px;

  color: $s-white;
  box-shadow: 0 6px 14px rgba(21, 96, 224, 0.28);
}

/* Wraps the mark + name so the whole lockup is one clickable,
   keyboard-focusable "go home" control — same flex recipe
   .gsb-brand used to apply directly to its children, just one
   level deeper now.

   Deliberately NO hover/active state here: no background,
   no opacity dim, no outline on click. -webkit-tap-highlight
   is killed for the mobile flash, user-select is off so a
   double-click/tap doesn't select the text, and the only
   visible ring left is :focus-visible for keyboard users. */
.gsb-brand__link {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
  text-decoration: none;
  color: inherit;
  cursor: pointer;
  border-radius: 8px;
  -webkit-tap-highlight-color: transparent;
  -webkit-user-select: none;
  user-select: none;
  outline: none;
}

.gsb-brand__link,
.gsb-brand__link:link,
.gsb-brand__link:visited,
.gsb-brand__link:hover,
.gsb-brand__link:active,
.gsb-brand__link:focus {
  background: transparent;
  color: inherit;
  text-decoration: none;
  outline: none;
  box-shadow: none;
}

/* keyboard-only focus ring — mouse and touch clicks stay clean */
.gsb-brand__link:focus-visible {
  outline: 2px solid $s-blue;
  outline-offset: 3px;
}

.gsb.is-tight .gsb-brand__link {
  justify-content: center;
}

.gsb-brand__name {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  font-size: 17px;
  font-weight: 700;
  letter-spacing: -0.024em;
  color: $s-navy;
  transition: opacity 0.2s $s-ease;
  pointer-events: none; /* clicks always resolve on .gsb-brand__link */
}

.gsb.is-tight .gsb-brand {
  justify-content: center;
  padding: 0;
}

.gsb.is-tight .gsb-brand__name {
  opacity: 0;
  width: 0;
}

/* the toggle sits on the divider, half out of the rail, which
   is where people already look for it */
.gsb-toggle {
  position: absolute;
  top: 50%;
  right: -13px;
  margin-top: -13px;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  padding: 0;
  border: 1px solid $s-line;
  border-radius: 50%;
  background: $s-white;
  color: $s-ink-3;
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(10, 37, 64, 0.1);
  transition: color 0.3s $s-ease,
              border-color 0.3s $s-ease,
              transform 0.32s $s-ease;
  z-index: 2;
}

.gsb-toggle:hover {
  border-color: $s-blue-2;
  color: $s-blue-dk;
}

.gsb.is-tight .gsb-toggle { transform: rotate(180deg); }

.gsb-toggle:focus-visible {
  outline: 2px solid $s-blue;
  outline-offset: 2px;
}


/* =========================================================
   NAV
   ========================================================= */

.gsb-scroll {
  flex: 1;
  min-height: 0;
  padding: 16px 12px 10px;
  overflow-y: auto;
  overflow-x: visible;
  scrollbar-width: none;
}

.gsb-scroll::-webkit-scrollbar { display: none; }

.gsb-group { margin-bottom: 20px; }

.gsb-group:last-child { margin-bottom: 0; }

/* Three groups of two or three read as a structure. Six items
   in a flat column read as a list you have to search. */
.gsb .gsb-group__label {
  margin: 0 0 8px;
  padding: 0 10px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: $s-ink-4;
  white-space: nowrap;
  transition: opacity 0.2s $s-ease;
}

/* collapsed, the group becomes a hairline. The grouping is
   still felt without the words taking a row each. */
.gsb.is-tight .gsb-group__label {
  height: 1px;
  margin: 0 6px 12px;
  padding: 0;
  overflow: hidden;
  color: transparent;
  background: $s-line-2;
}

.gsb .gsb-list {
  display: grid;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.gsb-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  height: 42px;
  padding: 0 12px;
  border-radius: 10px;
  color: $s-ink-2;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: -0.008em;
  text-decoration: none;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.28s $s-ease, color 0.28s $s-ease;
}

/* Hover is a tint, nothing more. It must never be louder than
   the page you are actually on. */
.gsb-item:hover {
  background: $s-tint;
  color: $s-navy;
  text-decoration: none;
}

.gsb-item.is-on {
  background: $s-blue-1;
  color: $s-blue-dk;
  font-weight: 600;
}

.gsb-item.is-on:hover {
  background: $s-blue-1;
  color: $s-blue-dk;
}

/* a short bar on the leading edge, so the active item is
   findable by shape as well as by tint */
.gsb-item__bar {
  position: absolute;
  top: 50%;
  left: 0;
  width: 3px;
  height: 0;
  margin-top: 0;
  border-radius: 0 3px 3px 0;
  background: $s-blue;
  transition: height 0.3s $s-ease, margin-top 0.3s $s-ease;
}

.gsb-item.is-on .gsb-item__bar {
  height: 20px;
  margin-top: -10px;
}

.gsb-item__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  flex-shrink: 0;
}

.gsb-item__label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  transition: opacity 0.2s $s-ease;
}

.gsb.is-tight .gsb-item {
  justify-content: center;
  padding: 0;
  gap: 0;
}

.gsb.is-tight .gsb-item__label {
  opacity: 0;
  width: 0;
  flex: 0;
}

.gsb-item:focus-visible {
  outline: 2px solid $s-blue;
  outline-offset: 2px;
}


/* ---------- badges ---------- */

.gsb-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 20px;
  padding: 0 7px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
}

.gsb-badge--alert { background: $s-red-1;   color: $s-red; }
.gsb-badge--warn  { background: $s-amber-1; color: $s-amber; }

/* collapsed, the count becomes a dot on the icon. The number
   matters less than the fact that something is waiting. */
.gsb.is-tight .gsb-badge {
  position: absolute;
  top: 7px;
  right: 13px;
  min-width: 9px;
  width: 9px;
  height: 9px;
  padding: 0;
  font-size: 0;
  border: 2px solid $s-white;
}

.gsb.is-tight .gsb-badge--alert { background: $s-red; }
.gsb.is-tight .gsb-badge--warn  { background: $s-amber; }


/* ---------- tooltip ----------
   Only rendered while the labels are hidden, so it never
   repeats something already on screen.
   ------------------------------------------------------- */

.gsb-tip {
  position: absolute;
  top: 50%;
  left: calc(100% + 12px);
  display: flex;
  align-items: center;
  gap: 8px;
  height: 34px;
  padding: 0 13px;
  border-radius: 9px;
  background: $s-navy;
  color: $s-white;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-50%) translateX(-6px);
  pointer-events: none;
  box-shadow: 0 10px 28px rgba(10, 37, 64, 0.24);
  transition: opacity 0.22s $s-ease,
              visibility 0.22s $s-ease,
              transform 0.22s $s-ease;
  z-index: 60;
}

.gsb-tip::before {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  margin-top: -5px;
  border: 5px solid transparent;
  border-right-color: $s-navy;
}

.gsb-tip__n {
  padding: 1px 7px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.18);
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.gsb-item:hover .gsb-tip,
.gsb-item:focus-visible .gsb-tip,
.gsb-user:hover .gsb-tip {
  opacity: 1;
  visibility: visible;
  transform: translateY(-50%) translateX(0);
}


/* =========================================================
   WHO
   The old rail had no anchor at either end, so six circles
   floated in the middle of a tall column with nothing to sit
   against. A brand at the top and an account at the bottom
   give the eye somewhere to start and stop.
   ========================================================= */

.gsb-foot {
  padding: 10px 12px 14px;
  border-top: 1px solid $s-line-2;
  flex-shrink: 0;
}

.gsb-user {
  position: relative;
  display: flex;
  align-items: center;
  gap: 11px;
  height: 50px;
  padding: 0 10px;
  border-radius: 11px;
  transition: background 0.28s $s-ease;
}

.gsb-user:hover { background: $s-tint; }

.gsb-user__mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: 10px;
  background: $s-blue; /* Changed from $s-navy */
  color: $s-white;
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.03em;
}

.gsb-user__body {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex: 1;
  transition: opacity 0.2s $s-ease;
}

.gsb-user__name {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 13.5px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: $s-navy;
}

.gsb-user__role {
  font-size: 11.5px;
  color: $s-ink-4;
}

.gsb-user__out {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  border-radius: 8px;
  color: $s-ink-4;
  text-decoration: none;
  transition: background 0.28s $s-ease, color 0.28s $s-ease;
}

.gsb-user__out:hover,
.gsb-user__out:focus {
  background: $s-red-1;
  color: $s-red;
  text-decoration: none;
}

.gsb.is-tight .gsb-user {
  justify-content: center;
  padding: 0;
  gap: 0;
}

.gsb.is-tight .gsb-user__body,
.gsb.is-tight .gsb-user__out {
  opacity: 0;
  width: 0;
  overflow: hidden;
}

.gsb-tip--user { font-weight: 600; }


/* =========================================================
   MOTION
   ========================================================= */

@media (prefers-reduced-motion: no-preference) {

  @keyframes gsbIn {
    from { opacity: 0; transform: translateX(-10px); }
    to   { opacity: 1; transform: translateX(0); }
  }

  .gsb-brand { animation: gsbIn 0.5s $s-ease backwards; }

  /* the groups arrive in reading order */
  .gsb-group { animation: gsbIn 0.5s $s-ease backwards; }

  .gsb-group:nth-child(1) { animation-delay: 0.05s; }
  .gsb-group:nth-child(2) { animation-delay: 0.11s; }
  .gsb-group:nth-child(3) { animation-delay: 0.17s; }

  .gsb-foot { animation: gsbIn 0.5s $s-ease 0.23s backwards; }
}


/* =========================================================
   NARROW
   Below this the rail is always tight, because a labelled rail
   plus a dashboard does not fit and the labels are the part
   that can be recovered on demand.
   ========================================================= */

@media (max-width: 900px) {

  .gsb,
  .gsb.is-tight {
    width: 68px;
    min-width: 68px;
    max-width: 68px;
  }

  .gsb .gsb-brand {
    justify-content: center;
    padding: 0;
  }

  .gsb .gsb-brand__name { opacity: 0; width: 0; }

  .gsb .gsb-toggle { display: none; }

  .gsb .gsb-group__label {
    height: 1px;
    margin: 0 6px 12px;
    padding: 0;
    overflow: hidden;
    color: transparent;
    background: $s-line-2;
  }

  .gsb .gsb-item {
    justify-content: center;
    padding: 0;
    gap: 0;
  }

  .gsb .gsb-item__label { opacity: 0; width: 0; flex: 0; }

  .gsb .gsb-user {
    justify-content: center;
    padding: 0;
    gap: 0;
  }

  .gsb .gsb-user__body,
  .gsb .gsb-user__out { opacity: 0; width: 0; overflow: hidden; }
}

@media (prefers-reduced-motion: reduce) {
  .gsb,
  .gsb * { transition: none; }
}

sp_widget.script:
(function () {

  /* =========================================================
     GATENOW · SIDEBAR
     Service Portal widget · Server script

     The nav is declared here rather than hardcoded in the
     template, so a page id changes in one place and the badge
     counts come from the same query the pages use.

     Every item carries a list of page ids it should light up
     for, because a section is usually more than one page: the
     programs list and a program detail are both Funding
     programs as far as an applicant is concerned.
     ========================================================= */

  var APPLICANT = 'x_enno_gatenow_service_applicants';
  var PROJECT   = 'x_enno_gatenow_project';
  var CLAIM     = 'x_enno_gatenow_reimbursement';

  var me = gs.getUserID();

  function opt(name, fallback) {
    var v = options[name];
    return (v === null || v === undefined || v === '') ? fallback : v.toString();
  }

  function lower(v) {
    return (v === null || v === undefined) ? '' : ('' + v).toLowerCase();
  }


  /* ---------- who ---------- */
  var u = gs.getUser();
  var fn = u.getFirstName() || '';
  var ln = u.getLastName() || '';

  data.userName = u.getDisplayName() || gs.getUserName();
  data.userInitials = (fn.charAt(0) + ln.charAt(0)).toUpperCase() ||
                      (data.userName || 'U').substring(0, 2).toUpperCase();

  data.orgLine = opt('org_line', gs.getMessage('Applicant'));

  /* the page currently open, so the rail can mark itself */
  data.current = lower($sp.getParameter('id') || '');

  /* dynamically build the logout url to redirect back to the current portal page */
  var portalSuffix = $sp.getPortalRecord().getValue('url_suffix');
  var redirectPage = data.current ? data.current : 'applicant_dashboard';
  data.logoutUrl = '/logout.do?sysparm_goto_url=/' + portalSuffix + '?id=' + redirectPage;


  /* ============================================================
     BADGES

     Only two numbers earn a badge: an award waiting on a
     decision, and a report due this month. Both cost the
     applicant something if ignored. A count of everything else
     is decoration that never changes and stops being read
     within a week.
     ============================================================ */

  var awaitingAwards = 0;
  var reportsDue = 0;

  try {

    var applicantIds = [];
    var ap = new GlideRecordSecure(APPLICANT);
    ap.addQuery('user', me);
    ap.query();
    while (ap.next()) {
      applicantIds.push(ap.getUniqueValue());
      if (lower(ap.getValue('state')) === 'award_pending') awaitingAwards++;
    }

    if (applicantIds.length) {

      /* open projects with nothing filed this month */
      var openProjects = [];
      var pj = new GlideRecordSecure(PROJECT);
      pj.addQuery('applicant', 'IN', applicantIds.join(','));
      pj.query();

      while (pj.next()) {
        var phase = lower(pj.getDisplayValue('phase'));
        if (phase.indexOf('closed') === -1 && phase.indexOf('cancel') === -1) {
          openProjects.push(pj.getUniqueValue());
        }
      }

      if (openProjects.length) {

        var g = new GlideDateTime();
        var thisMonth = g.getYearLocalTime() + '-' + ('0' + g.getMonthLocalTime()).slice(-2);

        var reported = {};
        var rp = new GlideRecordSecure('x_enno_gatenow_status_report');
        rp.addQuery('project', 'IN', openProjects.join(','));
        rp.query();

        while (rp.next()) {
          var raw = rp.getValue('status_date') || rp.getValue('sys_created_on');
          if (raw && ('' + raw).substring(0, 7) === thisMonth) {
            reported[rp.getValue('project')] = true;
          }
        }

        for (var i = 0; i < openProjects.length; i++) {
          if (!reported[openProjects[i]]) reportsDue++;
        }
      }
    }

  } catch (e) {
    gs.info('[Sidebar] badge counts unavailable: ' + e.message);
  }


  /* ============================================================
     NAV

     Grouped, because six flat items is a list and three groups
     of two is a structure. The groups follow the order of the
     work: find funding, track what you sent, then run what you
     won.
     ============================================================ */

  data.groups = [
    {
      key  : 'find',
      label: gs.getMessage('Find funding'),
      items: [
        {
          key  : 'overview',
          label: gs.getMessage('Overview'),
          icon : 'home',
          page : opt('page_overview', 'applicant_dashboard'),
          match: ['applicant_dashboard', 'overview']
        },
        {
          key  : 'programs',
          label: gs.getMessage('Funding programs'),
          icon : 'layers',
          page : opt('page_programs', 'my_funding_programs'),
          match: ['my_funding_programs', 'funding_programs', 'x_enno_gatenow_programs', 'x_enno_gatenow_program']
        }
      ]
    },
    {
      key  : 'track',
      label: gs.getMessage('Track'),
      items: [
        {
          key  : 'applications',
          label: gs.getMessage('My applications'),
          icon : 'file',
          page : opt('page_applications', 'my_applications'),
          match: ['my_applications', 'my_application_page', 'applicant_intake']
        },
        {
          key  : 'awards',
          label: gs.getMessage('My awards'),
          icon : 'award',
          page : opt('page_awards', 'awards'),
          match: ['awards', 'my_awards'],
          badge: awaitingAwards,
          badgeTone: 'alert'
        }
      ]
    },
    {
      key  : 'deliver',
      label: gs.getMessage('Deliver'),
      items: [
        {
          key  : 'projects',
          label: gs.getMessage('My projects'),
          icon : 'case',
          page : opt('page_projects', 'project'),
          match: ['project', 'my_projects']
        },
        {
          key  : 'reports',
          label: gs.getMessage('Reports and changes'),
          icon : 'chart',
          page : opt('page_reports', 'report_dashboard'),
          match: ['report_dashboard', 'reports_changes'],
          badge: reportsDue,
          badgeTone: 'warn'
        },
        {
          key  : 'money',
          label: gs.getMessage('Reimbursements'),
          icon : 'card',
          page : opt('page_reimbursements', 'reimbursement'),
          match: ['reimbursement', 'reimbursements']
        }
      ]
    }
  ];

  /* mark the open one on the server, so the rail is correct on
     first paint rather than after a digest */
  for (var gi = 0; gi < data.groups.length; gi++) {
    var items = data.groups[gi].items;
    for (var ii = 0; ii < items.length; ii++) {
      items[ii].active = items[ii].match.indexOf(data.current) !== -1;
    }
  }

  data.t = {
    brand    : opt('brand', 'GateNow'),
    collapse : gs.getMessage('Collapse menu'),
    expand   : gs.getMessage('Expand menu'),
    signOut  : gs.getMessage('Sign out'),
    awaiting : gs.getMessage('awaiting your decision'),
    dueNow   : gs.getMessage('reports due this month')
  };

})();
